Lemma sm0_probe_loop : forall RNG (POST : machine_state -> Prop)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a3 a4 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (FR : bvmap 5 word) fc (m : amem) (fs h : Z) (n : nat),
  Z.of_nat n < 16384 -> 0 <= fs -> fs + 11571200 < 2^64 ->
  a1 = Z_to_bv 64 (fs + 4096) -> a3 = Z_to_bv 64 16383 ->
  rng RNG fs 11571200 ->
  (forall j, (j < n)%nat -> rw_cells asegs m (fs + 4096 + Z.land (h + Z.of_nat j) 16383) [C1 (Z_to_bv 8 1)]) ->
  rw_cells asegs m (fs + 4096 + Z.land (h + Z.of_nat n) 16383) [C1 (Z_to_bv 8 0)] ->
  (forall a0 a2 a5 a6 a7 : word,
     a0 = Z_to_bv 64 (16384 - Z.of_nat n) -> a2 = Z_to_bv 64 (h + Z.of_nat n) ->
     a5 = Z_to_bv 64 (fs + 4096 + Z.land (h + Z.of_nat n) 16383) -> a6 = Z_to_bv 64 (Z.land (h + Z.of_nat n) 16383) ->
     a7 = Z_to_bv 64 0 ->
     evtF asegs RNG POST
       (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
           FR (Z_to_bv 64 0x3cd70) fc None m (seg_rom asegs))) ->
  forall (i : nat) (a0 a2 a5 a6 a7 : word), (i <= n)%nat ->
  a0 = Z_to_bv 64 (16384 - Z.of_nat i) -> a2 = Z_to_bv 64 (h + Z.of_nat i) ->
  evtF asegs RNG POST
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        FR (Z_to_bv 64 0x3ccf8) fc None m (seg_rom asegs)).
